mapper.update:
UPDATE proj_project_node_execution SET current_marker=NULL
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.executionId}
  AND version=#{query.expectedVersion} AND current_marker=1 AND status IN ('DONE','TERMINATED') AND deleted=0

UPDATE proj_project_task
SET status=#{query.initialStatus}, actual_start_time=NULL, actual_end_time=NULL, progress=0,
    version=version+1, updater=#{query.updater}, update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.taskId}
  AND version=#{query.expectedVersion} AND status=#{query.expectedStatus}
  AND status IN ('DONE','CLOSED') AND deleted=0

UPDATE proj_project SET version=version+1, updater=#{query.updater}, update_time=CURRENT_TIMESTAMP(3)
WHERE tenant_id=#{query.tenantId} AND id=#{query.projectId} AND active_plan_version_id=#{query.planVersionId}
  AND version=#{query.expectedVersion} AND lifecycle_status='ACTIVE' AND deleted=0
